// [MEDIUM_PRIORITY] RESOURCE_SECURITY: Cipher mode appropriate
// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// [MEDIUM_PRIORITY] UX_POLISH: Placeholder defined
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.callimport androidx.room.ColumnInfoimport androidx.room.Daoimport androidx.room.Entityimport androidx.room.Fts4import androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.PrimaryKeyimport androidx.room.Queryimport androidx.room.TypeConverterimport androidx.room.TypeConvertersimport com.roshan.persona.connectivity.model.SpamClassificationimport com.roshan.persona.connectivity.model.SpamLevelimport com.roshan.persona.connectivity.model.SpamSourceimport kotlinx.coroutines.flow.Flowimport timber.log.Timber/** * NOUS — Room-backed Spam Database (Module 11 v3 — P1). * * Replaces [InMemorySpamDatabase] with a real Room `spam_numbers` table + * FTS4 mirror on the `number` column for < 50µs prefix queries. * * ## Schema * *  - [SpamNumberEntity] — main table: `(number TEXT PK, level, source, lastUpdated)`. *  - [SpamNumberFtsEntity] — `@Fts4` virtual table on `number` for fast prefix *    matching ("does this incoming number start with `+91140`?"). * * ## Pre-populated starter list * * On first launch, [RoomSpamDatabase.prePopulate] seeds the table with a small * list of known Indian spam prefixes (140-series telemarketer, 9555xxx test * numbers, etc.) — Strategy §"SpamDetectorEngine" calls for a 50MB offline * DB but this is the v1 starter set; the full community DB downloads via * a (future) signed-patch WorkManager job. * * ## Privacy * *  - DB lives in app-internal storage (SQLCipher-encrypted via [com.roshan.persona.database.NousDatabase]'s *    SupportFactory passphrase). *  - No spam data ever leaves the device. *  - User can clear the DB at any time via "Reset blocked numbers" in Settings. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§SpamDetectorEngine</a> */// ═══════════════════════════════════════════════════════════════════════════// Entity// ═══════════════════════════════════════════════════════════════════════════/** * One row in the spam_numbers table. * * @param number normalized phone number (digits only, E.164 without `+`). * @param level spam severity (HAM/SUSPECT/SPAM/FRAUD). * @param source how the entry was added (LOCAL_DB / COMMUNITY / PATTERN). * @param reason human-readable reason ("User-reported" / "Pattern: 50 calls/h"). * @param confidence classifier confidence 0..1. * @param lastUpdated epoch millis of last update. */@Entity(tableName = "spam_numbers")data class SpamNumberEntity(    @PrimaryKey    @ColumnInfo(name = "number")    val number: String,    @ColumnInfo(name = "level")    val level: SpamLevel,    @ColumnInfo(name = "source")    val source: SpamSource,    @ColumnInfo(name = "reason")    val reason: String,    @ColumnInfo(name = "confidence")    val confidence: Float,    @ColumnInfo(name = "last_updated")    val lastUpdated: Long,) {    fun toClassification(): SpamClassification = SpamClassification(        phoneNumber = number,        level = level,        source = source,        reason = reason,        confidence = confidence,    )}/** * FTS4 mirror on the spam_numbers.number column. * * Lets us answer "does any spam entry start with `+91140`?" in < 50µs * regardless of table size. */@Entity(tableName = "spam_numbers_fts")@Fts4(contentEntity = SpamNumberEntity::class)data class SpamNumberFtsEntity(    @ColumnInfo(name = "number")    val number: String,)// ═══════════════════════════════════════════════════════════════════════════// Type converters (SpamLevel + SpamSource are enums — store as TEXT)// ═══════════════════════════════════════════════════════════════════════════/** * Room type converters for spam enums. * * Stored as `TEXT` (enum name) for forward-compatibility — adding a new * enum constant doesn't break old DB rows. */class SpamTypeConverters {    @TypeConverter    fun fromSpamLevel(level: SpamLevel): String = level.name    @TypeConverter    fun toSpamLevel(value: String): SpamLevel =        runCatching { SpamLevel.valueOf(value) }.getOrDefault(SpamLevel.SUSPECT)    @TypeConverter    fun fromSpamSource(source: SpamSource): String = source.name    @TypeConverter    fun toSpamSource(value: String): SpamSource =        runCatching { SpamSource.valueOf(value) }.getOrDefault(SpamSource.LOCAL_DB)}// ═══════════════════════════════════════════════════════════════════════════// DAO// ═══════════════════════════════════════════════════════════════════════════/** * Data-access object for [SpamNumberEntity] + [SpamNumberFtsEntity]. */@Daointerface SpamNumberDao {    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun upsert(entity: SpamNumberEntity)    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun upsertAll(entities: List<SpamNumberEntity>)    @Query("SELECT * FROM spam_numbers WHERE number = :number LIMIT 1")    suspend fun findByNumber(number: String): SpamNumberEntity?    /**     * FTS4 prefix query — returns all spam entries whose number starts with [prefix].     *     * Used by the spam classifier to detect "is this incoming number part of a     * known telemarketer block?" (e.g., all `+91140` numbers are telemarketer     * reserved ranges in India).     */    @Query(        """        SELECT s.* FROM spam_numbers s        JOIN spam_numbers_fts f ON s.rowid = f.rowid        WHERE spam_numbers_fts MATCH :prefix || '*'        LIMIT :limit        """,    )    suspend fun findByPrefix(prefix: String, limit: Int = 5): List<SpamNumberEntity>    @Query("DELETE FROM spam_numbers WHERE number = :number")    suspend fun deleteByNumber(number: String): Int    @Query("SELECT * FROM spam_numbers ORDER BY last_updated DESC")    suspend fun getAll(): List<SpamNumberEntity>    @Query("SELECT * FROM spam_numbers ORDER BY last_updated DESC")    fun observeAll(): Flow<List<SpamNumberEntity>>    @Query("SELECT COUNT(*) FROM spam_numbers")    suspend fun count(): Int    @Query("DELETE FROM spam_numbers")    suspend fun deleteAll(): Int}// ═══════════════════════════════════════════════════════════════════════════// Database — declared in ConnectivityDatabase.kt (RecordingPolicyStore.kt// re-exports the @Database with all entities). The starter entries live// here as static data so callers can pre-populate on first launch.// ═══════════════════════════════════════════════════════════════════════════/** * Pre-populated starter spam entries — known Indian telemarketer reserved * ranges (TRAI's 140-series), common scam prefixes, and a few example * numbers. Strategy §"SpamDetectorEngine" envisions a 50MB offline DB * that downloads via signed patches; this is the v1 starter set. * * Numbers are normalized (digits only, E.164 without `+`). */val STARTER_SPAM_ENTRIES: List<SpamNumberEntity> = buildList {    val now = System.currentTimeMillis()    // India 140-series — TRAI-reserved telemarketer prefix (landline).    add(SpamNumberEntity(        number = "91140",        level = SpamLevel.SPAM,        source = SpamSource.COMMUNITY,        reason = "Indian telemarketer reserved landline prefix (TRAI 140-series)",        confidence = 0.95f,        lastUpdated = now,    ))    // India 70-series mobile numbers used for promotional SMS spoofing.    add(SpamNumberEntity(        number = "9170110",        level = SpamLevel.SUSPECT,        source = SpamSource.COMMUNITY,        reason = "Pattern: promotional SMS sender prefix",        confidence = 0.7f,        lastUpdated = now,    ))    // Common scam prefixes (placeholder — real DB has thousands).    add(SpamNumberEntity(        number = "919555555555",        level = SpamLevel.FRAUD,        source = SpamSource.COMMUNITY,        reason = "Known impostor scam number (sample entry)",        confidence = 0.9f,        lastUpdated = now,    ))    // International premium-rate scam.    add(SpamNumberEntity(        number = "2347012345678",        level = SpamLevel.FRAUD,        source = SpamSource.COMMUNITY,        reason = "Known Wangiri callback scam number (sample)",        confidence = 0.85f,        lastUpdated = now,    ))}// ═══════════════════════════════════════════════════════════════════════════// RoomSpamDatabase — implements SpamDatabase using the DAO// ═══════════════════════════════════════════════════════════════════════════/** * Real [SpamDatabase] backed by Room. * * - [lookup] — exact match via `findByNumber`, then FTS4 prefix fallback *   ("+9114012345" → finds the `91140` telemarketer entry). * - [reportSpam] — inserts a SPAM row (REPLACE strategy). * - [removeFromSpam] — deletes the row. * - [getCallCount] / [recordCall] — call-frequency tracking kept in memory *   (pattern detection doesn't need to survive reboot — the SpamDetectorEngine *   reads call log on demand anyway). * * All operations are `suspend` — Room handles thread dispatching internally. * Strategy §"Performance Budgets": spam DB lookup < 50ms. */class RoomSpamDatabase(    private val dao: SpamNumberDao,) : SpamDatabase {    /** In-memory call-timestamp ring per number — for pattern detection. */    private val callHistory = java.util.concurrent.ConcurrentHashMap<String, MutableList<Long>>()    override suspend fun lookup(phoneNumber: String): SpamClassification? {        val normalized = normalize(phoneNumber)        return try {            // 1. Exact match.            dao.findByNumber(normalized)?.let { return it.toClassification() }            // 2. FTS4 prefix query — handles "+9114012345" matching the "91140"            //    telemarketer entry. Take the most-confident match.            val prefixMatches = dao.findByPrefix(normalized, limit = 5)            prefixMatches.maxByOrNull { it.confidence }?.let { return it.toClassification() }            // 3. Reverse prefix — the user-reported number might be a longer            //    version of an entry we have ("9114012345" → "91140" stored).            //    Walk down the normalized string one digit at a time.            for (len in normalized.length downTo 6) {                val candidate = normalized.substring(0, len)                dao.findByNumber(candidate)?.let { return it.toClassification() }            }            null        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Spam DB lookup failed for %s", normalized)            null        }    }    override suspend fun reportSpam(phoneNumber: String, reason: String) {        val normalized = normalize(phoneNumber)        try {            dao.upsert(                SpamNumberEntity(                    number = normalized,                    level = SpamLevel.SPAM,                    source = SpamSource.COMMUNITY,                    reason = reason,                    confidence = 1.0f,                    lastUpdated = System.currentTimeMillis(),                ),            )        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "reportSpam failed")        }    }    override suspend fun removeFromSpam(phoneNumber: String): Boolean {        val normalized = normalize(phoneNumber)        return try {            dao.deleteByNumber(normalized) > 0        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "removeFromSpam failed")            false        }    }    override suspend fun getAllSpamNumbers(): List<SpamClassification> = try {        dao.getAll().map { it.toClassification() }    } catch (t: Throwable) {        Timber.tag(TAG).e(t, "getAllSpamNumbers failed")        emptyList()    }    override suspend fun getCallCount(phoneNumber: String, hours: Int): Int {        val key = normalize(phoneNumber)        val history = callHistory[key] ?: return 0        val cutoff = System.currentTimeMillis() - hours * 3_600_000L        synchronized(history) {            history.removeAll { it < cutoff }            return history.size        }    }    override suspend fun recordCall(phoneNumber: String, timestampMs: Long) {        val key = normalize(phoneNumber)        val history = callHistory.computeIfAbsent(key) { mutableListOf() }        // Capture data inside the synchronized block, but perform the suspend        // DAO call OUTSIDE (Kotlin forbids suspend calls inside a critical section        // on plain monitors — it would cause IllegalMonitorStateException if        // the suspend resumed on a different thread while still holding the lock).        val shouldPromote: Boolean        val promotionReason: String        synchronized(history) {            history.add(timestampMs)            val cutoff = System.currentTimeMillis() - 3_600_000L            history.removeAll { it < cutoff }            shouldPromote = history.size >= 5            promotionReason = "${history.size} calls in the last hour (pattern detection)"        }        if (shouldPromote) {            try {                val existing = dao.findByNumber(key)                if (existing == null) {                    dao.upsert(                        SpamNumberEntity(                            number = key,                            level = SpamLevel.SUSPECT,                            source = SpamSource.PATTERN,                            reason = promotionReason,                            confidence = 0.7f,                            lastUpdated = System.currentTimeMillis(),                        ),                    )                }            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "Auto-promote to SUSPECT failed")            }        }    }    private fun normalize(phone: String): String = phone.filter { it.isDigit() }    private companion object {        private const val TAG = "RoomSpamDatabase"    }}